// Extraer chat_id, texto del paciente y nombre
const item = $input.first().json;
let chat_id = null;
let text = '';
let user_name = '';

if (item.message) {
  chat_id = String(item.message.chat.id);
  text = item.message.text || '';
  user_name = item.message.from.first_name || 'Paciente';
} else if (item.callback_query) {
  chat_id = String(item.callback_query.message.chat.id);
  text = item.callback_query.data || '';
  user_name = item.callback_query.from.first_name || 'Paciente';
}

return [{
  json: {
    chat_id,
    text,
    user_name,
    sessionId: chat_id
  }
}];

let input = {};
if (typeof query === 'object' && query !== null) {
  input = query;
} else if (typeof query === 'string') {
  try {
    input = JSON.parse(query);
  } catch (e) {
    input = { raw: query };
  }
}
const rawStr = JSON.stringify(input).toLowerCase();

const dias = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

function formatFechaEsp(d) {
  return dias[d.getDay()] + ' ' + d.getDate() + ' de ' + meses[d.getMonth()] + ' de ' + d.getFullYear();
}

function toIsoDate(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

// Calcular dinámicamente los próximos días hábiles a partir de hoy en tiempo real
const hoy = new Date();
const diasHabiles = [];
let cursor = new Date(hoy);

while (diasHabiles.length < 3) {
  cursor.setDate(cursor.getDate() + 1);
  const dw = cursor.getDay();
  if (dw !== 0 && dw !== 6) { // Lunes a Viernes
    diasHabiles.push({
      fecha_iso: toIsoDate(cursor),
      nombre_dia: formatFechaEsp(cursor),
      turnos_disponibles: ['10:30', '12:00', '16:30', '17:30']
    });
  }
}

// Si se pide una hora restringida (ej: 15:00)
if (rawStr.includes('15:00') || (input.hora && input.hora.includes('15:00'))) {
  return JSON.stringify({
    disponible: false,
    motivo: 'El turno de las 15:00 está reservado para una cirugía prolongada en el consultorio.',
    alternativas_disponibles: ['15:45', '16:30', '17:15', '18:00'],
    proximos_dias_habiles: diasHabiles
  });
}

return JSON.stringify({
  disponible: true,
  fecha_actual_sistema: toIsoDate(hoy),
  proximos_dias_habiles: diasHabiles,
  primer_dia_habil_disponible: diasHabiles[0],
  jornada: '08:30 a 20:30 h de lunes a viernes en los 6 consultorios de la clínica',
  regla_estricta: 'Ofrece obligatoriamente turnos en el PRÓXIMO DÍA HÁBIL disponible (' + diasHabiles[0].nombre_dia + '). Jamás ofrezcas fechas pasadas.'
});

